import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { Agent, type SessionEvent } from "../src/index.js";
import { MockProxy } from "./mock-proxy.js";

let proxy: MockProxy;
let baseUrl: string;

beforeEach(async () => {
  proxy = new MockProxy({ apiKey: "k" });
  baseUrl = await proxy.start();
});
afterEach(() => proxy.stop());

describe("roundtrip", () => {
  it("create → createSession → send → stream → getSession", async () => {
    const agent = await Agent.create({
      apiKey: "k",
      baseUrl,
      model: "anthropic/claude-haiku-4-5",
      templateId: "tpl_smoke",
      name: "x",
      prompt: "be terse",
    });
    expect(agent.id).toMatch(/^agent_/);
    expect(agent.model).toBe("anthropic/claude-haiku-4-5");
    expect(agent.templateId).toBe("tpl_smoke");

    const session = await agent.createSession({ initialPrompt: "hi" });
    expect(session.agentId).toBe(agent.id);
    expect(session.status).toBe("ready");

    const reply = await session.send("hello?");
    expect(reply).toEqual({ text: "echo: hello?" });

    const events: SessionEvent[] = [];
    for await (const ev of session.events()) events.push(ev);
    expect(events.map((e) => e.type)).toEqual([
      "session.started",
      "message.delta",
      "message.delta",
      "message.completed",
    ]);

    const again = await agent.getSession(session.id);
    expect(again.id).toBe(session.id);
  });

  it("forwards harnessId as snake_case harness_id on the wire", async () => {
    await Agent.create({
      apiKey: "k",
      baseUrl,
      model: "anthropic/claude-haiku-4-5",
      templateId: "tpl",
      harnessId: "claude-agent-sdk",
    });
    expect(proxy.lastCreateAgentBody?.harness_id).toBe("claude-agent-sdk");
  });

  it("omits harness_id when harnessId is unset (server picks default)", async () => {
    await Agent.create({
      apiKey: "k",
      baseUrl,
      model: "anthropic/claude-haiku-4-5",
      templateId: "tpl",
    });
    expect(proxy.lastCreateAgentBody).not.toHaveProperty("harness_id");
  });

  it("rejects on bad apiKey", async () => {
    await expect(
      Agent.create({
        apiKey: "wrong",
        baseUrl,
        model: "noop",
        templateId: "tpl",
      }),
    ).rejects.toThrow(/401/);
  });
});

import { describe, expect, it } from "vitest";
import { camel, snake } from "../src/wire.js";

describe("wire", () => {
  it("snake nested", () => {
    expect(snake({ apiKey: "k", repos: [{ startingRef: "main" }] })).toEqual({
      api_key: "k",
      repos: [{ starting_ref: "main" }],
    });
  });

  it("camel nested", () => {
    expect(camel({ session_id: "s", agent_id: "a" })).toEqual({ sessionId: "s", agentId: "a" });
  });

  it("passes scalars", () => {
    expect(camel(42)).toBe(42);
    expect(snake("x")).toBe("x");
    expect(camel(null)).toBeNull();
  });
});

import { createServer, type IncomingMessage, type Server, type ServerResponse } from "node:http";
import { randomUUID } from "node:crypto";
import { URL } from "node:url";

interface SessionRow {
  id: string;
  agent_id: string;
  status: "ready" | "creating" | "failed";
  sandbox_url?: string;
  messages: { text: string; reply: Record<string, unknown> }[];
  events: Record<string, unknown>[];
}

export interface MockOptions {
  apiKey?: string;
  /** Drop the SSE socket after this many events on the next /events call (single-shot). */
  dropAfter?: number;
  /** If set, /sessions/:id/events will use these events instead of the session's queue. */
  sessionEvents?: Record<string, unknown>[];
}

export class MockProxy {
  private server: Server;
  private port = 0;
  agents = new Map<string, { id: string; name: string | null; model: string; template_id: string }>();
  sessions = new Map<string, SessionRow>();
  /** Raw body of the most recent POST /v1/managed_agents/agents. Tests assert wire shape against this. */
  lastCreateAgentBody: Record<string, unknown> | null = null;
  opts: MockOptions;

  constructor(opts: MockOptions = {}) {
    this.opts = opts;
    this.server = createServer((req, res) => this.handle(req, res));
  }

  async start(): Promise<string> {
    await new Promise<void>((r) => this.server.listen(0, "127.0.0.1", r));
    this.port = (this.server.address() as { port: number }).port;
    return `http://127.0.0.1:${this.port}`;
  }

  stop(): Promise<void> {
    this.server.closeAllConnections?.();
    return new Promise((r) => this.server.close(() => r()));
  }

  private json(res: ServerResponse, status: number, body: unknown) {
    res.statusCode = status;
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify(body));
  }

  private body(req: IncomingMessage): Promise<Record<string, unknown>> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      req.on("data", (c) => chunks.push(c));
      req.on("end", () => {
        const t = Buffer.concat(chunks).toString();
        resolve(t ? JSON.parse(t) : {});
      });
      req.on("error", reject);
    });
  }

  private async handle(req: IncomingMessage, res: ServerResponse) {
    if (this.opts.apiKey && req.headers.authorization !== `Bearer ${this.opts.apiKey}`) {
      return this.json(res, 401, { error: "unauthorized" });
    }
    const url = new URL(req.url ?? "/", `http://x`);
    const p = url.pathname;
    const m = req.method;

    if (m === "POST" && p === "/v1/managed_agents/agents") {
      const b = await this.body(req);
      this.lastCreateAgentBody = b;
      const id = `agent_${randomUUID()}`;
      const row = {
        id,
        name: (b.name as string | undefined) ?? null,
        model: String(b.model ?? ""),
        template_id: String(b.template_id ?? ""),
      };
      this.agents.set(id, row);
      return this.json(res, 200, row);
    }

    let mt = p.match(/^\/v1\/managed_agents\/agents\/([^/]+)\/session$/);
    if (mt && m === "POST") {
      const agentId = mt[1]!;
      if (!this.agents.has(agentId)) return this.json(res, 404, {});
      const id = `session_${randomUUID()}`;
      const row: SessionRow = {
        id,
        agent_id: agentId,
        status: "ready",
        sandbox_url: `http://sandbox.test/${id}`,
        messages: [],
        events: [],
      };
      this.sessions.set(id, row);
      return this.json(res, 200, {
        id,
        agent_id: agentId,
        status: row.status,
        sandbox_url: row.sandbox_url,
      });
    }

    mt = p.match(/^\/v1\/managed_agents\/sessions\/([^/]+)$/);
    if (mt && m === "GET") {
      const s = this.sessions.get(mt[1]!);
      return s
        ? this.json(res, 200, {
            id: s.id,
            agent_id: s.agent_id,
            status: s.status,
            sandbox_url: s.sandbox_url,
          })
        : this.json(res, 404, {});
    }

    mt = p.match(/^\/v1\/managed_agents\/sessions\/([^/]+)\/message$/);
    if (mt && m === "POST") {
      const s = this.sessions.get(mt[1]!);
      if (!s) return this.json(res, 404, {});
      const b = await this.body(req);
      const reply = { text: `echo: ${String(b.text ?? "")}` };
      s.messages.push({ text: String(b.text ?? ""), reply });
      return this.json(res, 200, reply);
    }

    mt = p.match(/^\/v1\/managed_agents\/sessions\/([^/]+)\/(events|stream)$/);
    if (mt && m === "GET") {
      const s = this.sessions.get(mt[1]!);
      if (!s) return this.json(res, 404, {});
      const events = this.opts.sessionEvents ?? [
        { type: "session.started", session_id: s.id },
        { type: "message.delta", text: "hello " },
        { type: "message.delta", text: "world" },
        { type: "message.completed", text: "hello world" },
      ];

      res.statusCode = 200;
      res.setHeader("Content-Type", "text/event-stream");
      res.flushHeaders?.();

      const drop = this.opts.dropAfter ?? 0;
      let n = 0;
      for (const ev of events) {
        res.write(`data: ${JSON.stringify(ev)}\n\n`);
        n++;
        if (drop > 0 && n >= drop) {
          this.opts.dropAfter = 0;
          res.socket?.destroy();
          return;
        }
      }
      return res.end();
    }

    this.json(res, 404, { error: "no_route", path: p, method: m });
  }
}

/**
 * End-to-end test for `createClaudeStream` — feeds the helper a scripted
 * SSE stream of `claude_sdk_message` envelopes wrapping real Anthropic
 * `SDKMessage` payloads, and asserts the resulting `ClaudeStreamState`
 * surfaces every message in order, then transitions to `idle`.
 */
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  Agent,
  createClaudeStream,
  foldSdkMessages,
  type SDKMessage,
} from "../src/index.js";
import { MockProxy } from "./mock-proxy.js";

let proxy: MockProxy;
let baseUrl: string;

beforeEach(async () => {
  proxy = new MockProxy({ apiKey: "k" });
  baseUrl = await proxy.start();
});
afterEach(() => proxy.stop());

async function provisionSession(): Promise<string> {
  const agent = await Agent.create({
    apiKey: "k",
    baseUrl,
    model: "anthropic/claude-haiku-4-5",
    templateId: "tpl_smoke",
  });
  const session = await agent.createSession({ initialPrompt: "go" });
  return session.id;
}

describe("createClaudeStream", () => {
  it("yields SDKMessages through to session.idle", async () => {
    proxy.opts.sessionEvents = [
      { type: "stream.opened" },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "system",
            subtype: "init",
            session_id: "ses_1",
          },
        },
      },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "assistant",
            message: {
              id: "msg_api_1",
              role: "assistant",
              content: [{ type: "text", text: "Hello!" }],
            },
            session_id: "ses_1",
          },
        },
      },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "result",
            subtype: "success",
            result: "Hello!",
            total_cost_usd: 0.001,
          },
        },
      },
      { type: "session.idle", properties: { sessionID: "ses_1" } },
    ];

    const sid = await provisionSession();
    const stream = createClaudeStream({
      apiKey: "k",
      baseUrl,
      sessionId: sid,
    });
    await stream.done();

    const final = stream.state();
    expect(final.status).toBe("idle");
    expect(final.messages).toHaveLength(3);
    expect(final.messages.map((m) => m.type)).toEqual([
      "system",
      "assistant",
      "result",
    ]);
  });

  it("ignores legacy message.part.* envelopes from the harness", async () => {
    // The harness emits both the new claude_sdk_message events AND the
    // legacy message.part.updated / .delta events during transition. The
    // native stream consumer must ignore the legacy stream.
    proxy.opts.sessionEvents = [
      { type: "stream.opened" },
      {
        type: "message.part.updated",
        properties: {
          messageID: "msg_legacy",
          part: { id: "p0", type: "text", text: "ignored" },
        },
      },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "assistant",
            message: {
              id: "msg_new",
              role: "assistant",
              content: [{ type: "text", text: "kept" }],
            },
            session_id: "ses_1",
          },
        },
      },
      { type: "session.idle", properties: { sessionID: "ses_1" } },
    ];

    const sid = await provisionSession();
    const stream = createClaudeStream({
      apiKey: "k",
      baseUrl,
      sessionId: sid,
    });
    await stream.done();
    expect(stream.state().messages).toHaveLength(1);
    expect(stream.state().messages[0].type).toBe("assistant");
  });

  it("session.error transitions to error with message", async () => {
    proxy.opts.sessionEvents = [
      { type: "stream.opened" },
      {
        type: "session.error",
        properties: { sessionID: "ses_1", message: "agent crashed" },
      },
    ];
    const sid = await provisionSession();
    const stream = createClaudeStream({
      apiKey: "k",
      baseUrl,
      sessionId: sid,
    });
    await stream.done();
    expect(stream.state().status).toBe("error");
    expect(stream.state().error).toBe("agent crashed");
  });

  it("works alongside foldSdkMessages for a clean rendering list", async () => {
    proxy.opts.sessionEvents = [
      { type: "stream.opened" },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "stream_event",
            event: {
              type: "message_start",
              message: {
                id: "msg_partial",
                role: "assistant",
                content: [],
              },
            },
          },
        },
      },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "stream_event",
            event: {
              type: "content_block_start",
              index: 0,
              content_block: { type: "text", text: "" },
            },
          },
        },
      },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "stream_event",
            event: {
              type: "content_block_delta",
              index: 0,
              delta: { type: "text_delta", text: "Hello " },
            },
          },
        },
      },
      {
        type: "claude_sdk_message",
        properties: {
          message: {
            type: "stream_event",
            event: {
              type: "content_block_delta",
              index: 0,
              delta: { type: "text_delta", text: "world" },
            },
          },
        },
      },
      { type: "session.idle", properties: { sessionID: "ses_1" } },
    ];
    const sid = await provisionSession();
    const stream = createClaudeStream({
      apiKey: "k",
      baseUrl,
      sessionId: sid,
    });
    await stream.done();
    const folded = foldSdkMessages(stream.state().messages);
    expect(folded).toHaveLength(1);
    const text = (
      folded[0] as { message: { content: { text?: string }[] } }
    ).message.content[0]?.text;
    expect(text).toBe("Hello world");
  });
});

/**
 * Tests for `foldSdkMessages` — the helper that collapses the SDK's mixed
 * stream of `SDKAssistantMessage` snapshots and `SDKPartialAssistantMessage`
 * delta frames into a single rolling message list.
 *
 * Fixtures use the exact shapes from `@anthropic-ai/claude-agent-sdk`:
 *   - `type: "stream_event"` wrapping Anthropic's native `message_start`,
 *     `content_block_start`, `content_block_delta` frames.
 *   - `type: "assistant"` carrying the authoritative API message.
 */
import { describe, expect, it } from "vitest";
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const F = (m: any): any => m;
import { foldSdkMessages, type SDKMessage } from "../src/index.js";

describe("foldSdkMessages — passthrough", () => {
  it("returns user/result/system messages unchanged", () => {
    const stream: SDKMessage[] = [
      F({ type: "system", subtype: "init", session_id: "ses_1" }),
      F({ type: "user", message: { role: "user", content: "hi" } }),
      F({
        type: "result",
        subtype: "success",
        result: "done",
        total_cost_usd: 0.01,
      }),
    ];
    const out = foldSdkMessages(stream);
    expect(out).toHaveLength(3);
    expect(out.map((m) => m.type)).toEqual(["system", "user", "result"]);
  });

  it("passes through an authoritative assistant message verbatim", () => {
    const stream: SDKMessage[] = [
      F({
        type: "assistant",
        message: {
