export function snake(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(snake);
  if (v && typeof v === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, val] of Object.entries(v)) {
      out[k.replace(/[A-Z]/g, (m) => "_" + m.toLowerCase())] = snake(val);
    }
    return out;
  }
  return v;
}

export function camel(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(camel);
  if (v && typeof v === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, val] of Object.entries(v)) {
      out[k.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase())] = camel(val);
    }
    return out;
  }
  return v;
}

/**
 * Two endpoints, two pairs of credentials. Don't conflate them.
 *
 *   LiteLLM Agent Platform (LAP)   — `apiKey` + `baseUrl` on `ClientOptions`
 *                                    The control plane this SDK talks to:
 *                                    `POST /v1/managed_agents/agents`,
 *                                    `POST /v1/managed_agents/sessions/:id/message`,
 *                                    etc.
 *
